INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "A university noticed declining attendance in one of its large lecture courses. The professor surveyed students and learned the sessions felt too passive. She introduced short group discussions throughout each lecture. Attendance and engagement both improved noticeably over the semester."}'::jsonb, '{"key_points": ["a university noticed declining attendance", "the professor surveyed students about the sessions", "she introduced group discussions", "attendance and engagement improved"]}'::jsonb, 44, 0.55, 'B2', 'approved', 'exam', 'education', 'd4000000-0000-4000-8000-000000000012', 1),
('passage_reconstruction', '{"passage": "A hotel began receiving complaints about slow check-in during busy weekends. Managers reviewed the front-desk process and found only one staff member handled all arrivals. They added a second check-in station on weekends. Guest complaints dropped sharply within a month."}'::jsonb, '{"key_points": ["a hotel received complaints about slow check-in", "only one staff member handled arrivals", "they added a second check-in station", "complaints dropped within a month"]}'::jsonb, 42, 0.56, 'B2', 'approved', 'exam', 'business', 'd4000000-0000-4000-8000-000000000012', 2),
('passage_reconstruction', '{"passage": "Thank you for your recent feedback about the registration process. We understand that the new system caused delays for several students this term, and we sincerely apologize for the inconvenience. We have simplified the steps and added extra support staff for the next registration period."}'::jsonb, '{"key_points": ["thanks for feedback about registration", "apologizes for delays caused by the new system", "the steps have been simplified", "extra support staff were added"]}'::jsonb, 42, 0.56, 'B2', 'approved', 'exam', 'education', 'd4000000-0000-4000-8000-000000000012', 3);
