INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "Your university has had an increase in complaints about long advising wait times. Your manager, Dr. Haas, wants ideas for improving the advising process without hiring more staff. Write an email to her suggesting three ways to achieve this. Your suggestions must come from the following three themes: online booking, group advising sessions, extended office hours. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'education', 'd4000000-0000-4000-8000-000000000014', 1),
('email_writing', '{"prompt": "Your hotel is planning to improve its guest check-in experience. Your manager, Ms. Delacroix, wants ideas for the update. Write an email to her suggesting three priorities for the change. Your suggestions must come from the following three themes: mobile check-in, clearer signage, a dedicated welcome desk. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd4000000-0000-4000-8000-000000000014', 2);
