INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('story_retelling', '{"story": "A hotel concierge noticed guests often asked the same questions about local attractions. Instead of answering each one individually, he created a simple printed guide for the front desk. Guests appreciated having the information readily available. Front-desk calls about local attractions dropped significantly."}'::jsonb, null, 44, 0.52, 'B2', 'approved', 'exam', 'business', 'd4000000-0000-4000-8000-00000000001a', 1),
('story_retelling', '{"story": "A professor noticed that students rarely attended optional office hours. She decided to hold them online instead of in person. Attendance increased immediately, since students could join between other commitments. She now holds most of her office hours online."}'::jsonb, null, 42, 0.54, 'B2', 'approved', 'exam', 'education', 'd4000000-0000-4000-8000-00000000001a', 2),
('story_retelling', '{"story": "A hotel manager noticed that housekeeping sometimes missed rooms during busy checkout days. She introduced a simple checklist system for each floor. Staff began confirming every room before moving to the next. Missed rooms became extremely rare after the change."}'::jsonb, null, 44, 0.53, 'B2', 'approved', 'exam', 'business', 'd4000000-0000-4000-8000-00000000001a', 3);
